/* static/css/style.css */

/* General Reset */
body, div, h1, h2, h3, ul, li, p, a, button {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Body Styling */
body {
  font-family: 'Arial', sans-serif;
  background-color: #f9f9f9;
  color: #333;
  line-height: 1.6;
}

/* Header Styling */
header {
  background-color: #0077cc;
  color: #fff;
  padding: 20px 0;
  text-align: center;
}

header h1 {
  font-size: 2rem;
}

/* Navigation Bar */
nav {
  background-color: #005fa3;
  padding: 10px 0;
}

nav ul {
  display: flex;
  justify-content: center;
  list-style: none;
}

nav ul li {
  margin: 0 15px;
}

nav ul li a {
  color: #fff;
  text-decoration: none;
  font-weight: bold;
}

nav ul li a:hover {
  text-decoration: underline;
}

/* Main Content */
main {
  padding: 20px;
}

/* Problem Cards */
.problem-card {
  background: #fff;
  border: 1px solid #ddd;
  border-radius: 5px;
  padding: 15px;
  margin-bottom: 20px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.problem-card h2 {
  font-size: 1.5rem;
  margin-bottom: 10px;
}

.problem-card p {
  margin-bottom: 10px;
  color: #555;
}

.problem-card a {
  color: #0077cc;
  text-decoration: none;
}

.problem-card a:hover {
  text-decoration: underline;
}

/* Buttons */
button {
  background-color: #0077cc;
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #005fa3;
}

/* Footer Styling */
footer {
  background-color: #333;
  color: #fff;
  padding: 10px 0;
  text-align: center;
}

footer p {
  font-size: 0.9rem;
}

// static/js/app.js

// Purpose: Frontend JavaScript for dynamic interactions on the ACM Problem-Solving Platform
// Layer: Frontend

document.addEventListener("DOMContentLoaded", () => {
    // Fetch and display problem list
    const fetchProblems = async () => {
        try {
            const response = await fetch('/problems');
            const problems = await response.json();
            const problemList = document.getElementById('problem-list');
            problemList.innerHTML = '';
            problems.forEach(problem => {
                const listItem = document.createElement('li');
                listItem.innerHTML = `
                    <a href="/problems/${problem.id}">
                        ${problem.title} - ${problem.difficulty}
                    </a>
                `;
                problemList.appendChild(listItem);
            });
        } catch (error) {
            console.error("Error fetching problems:", error);
        }
    };

    // Submit a solution
    const submitSolution = async (problemId, code, language) => {
        try {
            const response = await fetch(`/solutions`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    problem_id: problemId,
                    code: code,
                    language: language,
                }),
            });
            const result = await response.json();
            if (response.ok) {
                alert("Solution submitted successfully!");
            } else {
                alert(`Error: ${result.message}`);
            }
        } catch (error) {
            console.error("Error submitting solution:", error);
        }
    };

    // Event listener for solution submission form
    const solutionForm = document.getElementById('solution-form');
    if (solutionForm) {
        solutionForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            const problemId = document.getElementById('problem-id').value;
            const code = document.getElementById('code').value;
            const language = document.getElementById('language').value;
            await submitSolution(problemId, code, language);
        });
    }

    // Fetch problems on page load
    if (document.getElementById('problem-list')) {
        fetchProblems();
    }
});
